def apply_oversight_names(apps, schema_editor):
    """
    11-16-26: name the education committee for what it is today (no VP of
    Education → "Education Oversight Committee"); from now on the role
    changing hands renames it (src/education_oversight.py).
    """
    Committee = apps.get_model('src', 'Committee')
    ParliamentUser = apps.get_model('src', 'ParliamentUser')
    SiteSetting = apps.get_model('src', 'SiteSetting')
    for committee in Committee.objects.filter(is_education_committee=True):
        held = bool(committee.role_id) and ParliamentUser.objects.filter(
            roles=committee.role_id, is_active=True, member_status='Active').exists()
        if held or committee.name == 'Education Oversight Committee':
            continue
        SiteSetting.objects.update_or_create(
            key='education_committee_usual_name',
            defaults={'value': committee.name, 'default_value': committee.name,
                      'description': "The education committee's name when it has a VP of Education "
                                     '(src/education_oversight.py).'})
        committee.name = 'Education Oversight Committee'
        committee.save(update_fields=['name'])


